static void InitializeNtApis()
{
	if (g_NtYieldExecution == NULL || g_NtQuerySystemInformation == NULL)
	{
		HMODULE hNtdll = GetModuleHandleW(L"ntdll.dll");
		if (hNtdll != NULL)
		{
			g_NtYieldExecution = (pfnNtYieldExecution)GetProcAddress(hNtdll, "NtYieldExecution");
			g_NtQuerySystemInformation = (pfnNtQuerySystemInformation)GetProcAddress(hNtdll, "NtQuerySystemInformation");
		}
	}
}

// ==============================================================================
// Memory Barrier & Serialized RDTSC/RDTSCP Timing Functions
// ==============================================================================
__forceinline uint64_t RdtscBenchmarkStart()
{
	_mm_mfence();
	_mm_lfence();
	uint64_t tsc = __rdtsc();
	_mm_lfence();
	return tsc;
}

__forceinline uint64_t RdtscBenchmarkEnd(unsigned int* outAux = nullptr)
{
	unsigned int aux = 0;
	_mm_lfence();
	uint64_t tsc = __rdtscp(&aux);
	_mm_lfence();
	_mm_mfence();
	if (outAux != nullptr)
	{
		*outAux = aux;
	}
	return tsc;
}

// ==============================================================================
// ScopedCpuAffinity Implementation
// ==============================================================================
ScopedCpuAffinity::ScopedCpuAffinity(DWORD CoreIndex)
	: m_OldAffinity(0), m_OldPriorityClass(0), m_OldThreadPriority(0), m_AffinitySet(false)
{
	m_OldPriorityClass = GetPriorityClass(GetCurrentProcess());
	m_OldThreadPriority = GetThreadPriority(GetCurrentThread());

	// Elevate process and thread priority to minimize scheduler interference
	if (!SetPriorityClass(GetCurrentProcess(), REALTIME_PRIORITY_CLASS))
	{
		SetPriorityClass(GetCurrentProcess(), HIGH_PRIORITY_CLASS);
	}
	SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_TIME_CRITICAL);

	// Pin thread to specified single core
	if (CoreIndex < sizeof(DWORD_PTR) * 8)
	{
		DWORD_PTR mask = (DWORD_PTR)1 << CoreIndex;
		DWORD_PTR prev = SetThreadAffinityMask(GetCurrentThread(), mask);
		if (prev != 0)
		{
			m_OldAffinity = prev;
			m_AffinitySet = true;
		}
	}

	// Brief sleep to allow OS scheduler migration to settle on chosen core
	Sleep(10);
}

ScopedCpuAffinity::~ScopedCpuAffinity()
{
	if (m_AffinitySet && m_OldAffinity != 0)
	{
		SetThreadAffinityMask(GetCurrentThread(), m_OldAffinity);
	}
	SetThreadPriority(GetCurrentThread(), m_OldThreadPriority);
	SetPriorityClass(GetCurrentProcess(), m_OldPriorityClass);
}

