BENCHMARK_RESULT RdtscBenchmark::MeasureBaseline(uint32_t Iterations)
{
	BENCHMARK_RESULT result;
	result.Name = "RDTSC + Fence Baseline";
	result.Iterations = Iterations;
	result.MinCycles = UINT64_MAX;

	// Warmup
	for (int w = 0; w < 500; ++w)
	{
		uint64_t s = RdtscBenchmarkStart();
		uint64_t e = RdtscBenchmarkEnd();
		(void)s; (void)e;
	}

	uint64_t total = 0;
	for (uint32_t i = 0; i < Iterations; ++i)
	{
		uint64_t start = RdtscBenchmarkStart();
		uint64_t end = RdtscBenchmarkEnd();
		uint64_t delta = (end >= start) ? (end - start) : 0;

		if (delta < result.MinCycles) result.MinCycles = delta;
		if (delta > result.MaxCycles) result.MaxCycles = delta;
		total += delta;
	}

	result.TotalCycles = total;
	result.AvgCycles = Iterations > 0 ? (total / Iterations) : 0;
	result.Diagnosis = "Harness Overhead (~20-50 cycles)";

	BENCHMARK_BREAKDOWN_STAGE s1;
	s1.StageName = "RDTSC + Memory Fence";
	s1.Cycles = result.MinCycles;
	s1.Color = "#4A90E2";
	result.Breakdown.push_back(s1);

	return result;
}

