static uint64_t MeasureSingleMsrIteration(uint32_t MsrIndex)
{
	uint64_t val = 0;
	uint64_t start = RdtscBenchmarkStart();
	__try
	{
		val = __readmsr(MsrIndex);
	}
	__except (EXCEPTION_EXECUTE_HANDLER)
	{
	}
	uint64_t end = RdtscBenchmarkEnd();
	(void)val;
	return (end >= start) ? (end - start) : 0;
}

