	s2.StageName = "EPT Violation / Page Flip";
	s2.Cycles = eptViolationCycles;
	s2.Color = "#E74C3C"; // Red
	result.Breakdown.push_back(s2);

	BENCHMARK_BREAKDOWN_STAGE s3;
	s3.StageName = "PostHook Dispatch & Filter";
	s3.Cycles = postHookLogicCycles;
	s3.Color = "#9B59B6"; // Purple
