// ==============================================================================
// Driver-Level Ring 0 Benchmark (Zero #GP Overhead, True Latency)
// ==============================================================================
std::vector<BENCHMARK_RESULT> RdtscBenchmark::QueryDriverBenchmark(HANDLE DriverHandle, uint32_t Iterations)
{
	std::vector<BENCHMARK_RESULT> results;
	if (DriverHandle == NULL || DriverHandle == INVALID_HANDLE_VALUE)
	{
		return results;
	}

	KERNEL_BENCHMARK_REQUEST req;
	req.Iterations = Iterations;

	KERNEL_BENCHMARK_RESPONSE resp;
	RtlZeroMemory(&resp, sizeof(resp));

	DWORD bytesReturned = 0;
	uint64_t userStart = RdtscBenchmarkStart();
	BOOL success = DeviceIoControl(
		DriverHandle,
		IOCTL_HV_BENCHMARK,
		&req,
		sizeof(req),
		&resp,
		sizeof(resp),
		&bytesReturned,
		NULL
	);
	uint64_t userEnd = RdtscBenchmarkEnd();
	uint64_t userTotalRoundtrip = (userEnd >= userStart) ? (userEnd - userStart) : 0;

	if (!success || resp.Count == 0)
	{
		DWORD err = GetLastError();
		std::cout << "    [!] Driver IOCTL_HV_BENCHMARK failed. Win32 Error: " << err << " (Returned bytes: " << bytesReturned << ", Count: " << resp.Count << ")\n";
		return results;
	}

	for (ULONG i = 0; i < resp.Count; ++i)
	{
		const auto& kItem = resp.Items[i];
		BENCHMARK_RESULT r;
		r.Name = kItem.Name;
		r.Iterations = Iterations;
		r.MinCycles = kItem.MinCycles;
		r.AvgCycles = kItem.AvgCycles;
		r.MaxCycles = kItem.MaxCycles;
		r.TotalCycles = kItem.TotalCycles;

		std::string nameStr = r.Name;
		if (nameStr.find("MSR") != std::string::npos)
		{
			if (r.MinCycles > 500)
			{
				r.Diagnosis = "True Hypervisor VM-Exit Latency (Zero #GP overhead!)";
				uint64_t base = 35;
				uint64_t vmExit = r.MinCycles > base ? (r.MinCycles - base) : 0;

				BENCHMARK_BREAKDOWN_STAGE s1;
				s1.StageName = "Bare-Metal MSR Base";
				s1.Cycles = base;
				s1.Color = "#27AE60";
				r.Breakdown.push_back(s1);

				BENCHMARK_BREAKDOWN_STAGE s2;
				s2.StageName = "Hypervisor VM-Exit Interception";
				s2.Cycles = vmExit;
				s2.Color = "#9B59B6";
				r.Breakdown.push_back(s2);
			}
			else
			{
				r.Diagnosis = "True Bare-Metal Ring 0 MSR (Zero #GP overhead!)";
				BENCHMARK_BREAKDOWN_STAGE s1;
				s1.StageName = "Native Ring 0 MSR Execution";
				s1.Cycles = r.MinCycles;
				s1.Color = "#27AE60";
				r.Breakdown.push_back(s1);
			}

			results.push_back(r);
		}
		else if (nameStr.find("CPUID") != std::string::npos)
		{
			// Ring 0 CPUID item
			if (r.MinCycles > 600)
			{
				r.Diagnosis = "Ring 0 VM-Exit Active (Hypervisor CPUID)";
				uint64_t base = 210;
				uint64_t vmExit = r.MinCycles > base ? (r.MinCycles - base) : 0;

				BENCHMARK_BREAKDOWN_STAGE s1;
				s1.StageName = "Bare-Metal CPUID Base";
				s1.Cycles = base;
				s1.Color = "#3498DB";
				r.Breakdown.push_back(s1);

				BENCHMARK_BREAKDOWN_STAGE s2;
				s2.StageName = "Ring 0 VM-Exit Interception";
				s2.Cycles = vmExit;
				s2.Color = "#9B59B6";
				r.Breakdown.push_back(s2);
			}
			else
			{
				r.Diagnosis = "Ring 0 Native CPUID (No VM-Exit)";
				BENCHMARK_BREAKDOWN_STAGE s1;
				s1.StageName = "Native Ring 0 CPUID";
				s1.Cycles = r.MinCycles;
				s1.Color = "#27AE60";
				r.Breakdown.push_back(s1);
			}

			results.push_back(r);
		}
	}

	return results;
}

// ==============================================================================
// JSON Exporter with Stage Breakdown Support
// ==============================================================================
static std::string GetFormattedTimestamp()
{
	SYSTEMTIME st;
	GetLocalTime(&st);
	char buf[64];
	sprintf_s(buf, "%04d-%02d-%02d %02d:%02d:%02d",
		st.wYear, st.wMonth, st.wDay, st.wHour, st.wMinute, st.wSecond);
	return std::string(buf);
}

static std::string JsonEscape(const std::string& input)
{
	std::string out;
	for (char c : input)
	{
		if (c == '"') out += "\\\"";
		else if (c == '\\') out += "\\\\";
		else if (c == '\n') out += "\\n";
		else if (c == '\r') out += "\\r";
		else if (c == '\t') out += "\\t";
		else out += c;
	}
	return out;
}

static std::string BuildSingleRunJson(
	int runId,
	const std::string& timestamp,
	DWORD CoreId,
	uint32_t Iterations,
	const std::vector<BENCHMARK_RESULT>& Results
)
{
	std::ostringstream ss;
	ss << "    {\n";
	ss << "      \"run_id\": " << runId << ",\n";
	ss << "      \"timestamp\": \"" << timestamp << "\",\n";
	ss << "      \"core_id\": " << CoreId << ",\n";
	ss << "      \"iterations\": " << Iterations << ",\n";
	ss << "      \"benchmarks\": [\n";

	for (size_t i = 0; i < Results.size(); ++i)
	{
		const auto& r = Results[i];
		ss << "        {\n";
		ss << "          \"name\": \"" << JsonEscape(r.Name) << "\",\n";
		ss << "          \"min_cycles\": " << r.MinCycles << ",\n";
		ss << "          \"avg_cycles\": " << r.AvgCycles << ",\n";
		ss << "          \"max_cycles\": " << r.MaxCycles << ",\n";
		ss << "          \"total_cycles\": " << r.TotalCycles << ",\n";
		ss << "          \"diagnosis\": \"" << JsonEscape(r.Diagnosis) << "\",\n";
		ss << "          \"breakdown\": [\n";

		for (size_t b = 0; b < r.Breakdown.size(); ++b)
		{
			const auto& st = r.Breakdown[b];
			ss << "            {\n";
			ss << "              \"stage\": \"" << JsonEscape(st.StageName) << "\",\n";
			ss << "              \"cycles\": " << st.Cycles << ",\n";
			ss << "              \"color\": \"" << JsonEscape(st.Color) << "\"\n";
			ss << "            }" << (b + 1 < r.Breakdown.size() ? "," : "") << "\n";
		}

		ss << "          ]\n";
		ss << "        }" << (i + 1 < Results.size() ? "," : "") << "\n";
	}

	ss << "      ]\n";
	ss << "    }";
	return ss.str();
}

bool RdtscBenchmark::SaveToJson(
	const std::string& Filename,
	const std::vector<BENCHMARK_RESULT>& Results,
	DWORD CoreId,
	uint32_t Iterations
)
{
	std::string timestamp = GetFormattedTimestamp();

	std::ifstream inFile(Filename);
	std::string existingContent;
	bool fileExists = false;

	if (inFile.is_open())
	{
		std::ostringstream buffer;
		buffer << inFile.rdbuf();
		existingContent = buffer.str();
		inFile.close();
		fileExists = !existingContent.empty();
	}

	int runId = 1;

	if (fileExists && existingContent.find("\"runs\"") != std::string::npos)
	{
		size_t pos = 0;
		int count = 0;
		while ((pos = existingContent.find("\"run_id\"", pos)) != std::string::npos)
		{
			count++;
			pos += 8;
		}
		runId = count + 1;

		std::string newRun = BuildSingleRunJson(runId, timestamp, CoreId, Iterations, Results);

		size_t lastBracket = existingContent.rfind(']');
		if (lastBracket != std::string::npos)
		{
			std::string updated = existingContent.substr(0, lastBracket);
			updated += ",\n" + newRun + "\n  ]\n}\n";

			size_t totalRunsPos = updated.find("\"total_runs\":");
			if (totalRunsPos != std::string::npos)
			{
				size_t commaPos = updated.find(',', totalRunsPos);
				if (commaPos != std::string::npos)
				{
					updated.replace(totalRunsPos, commaPos - totalRunsPos, "\"total_runs\": " + std::to_string(runId));
				}
			}

			std::ofstream outFile(Filename, std::ios::trunc);
			if (outFile.is_open())
			{
				outFile << updated;
				outFile.close();
				return true;
			}
		}
	}

	std::string singleRun = BuildSingleRunJson(runId, timestamp, CoreId, Iterations, Results);
	std::ofstream outFile(Filename, std::ios::trunc);
	if (!outFile.is_open())
	{
		std::cout << "[-] Failed to open " << Filename << " for writing.\n";
		return false;
	}

	outFile << "{\n";
	outFile << "  \"total_runs\": 1,\n";
	outFile << "  \"runs\": [\n";
	outFile << singleRun << "\n";
	outFile << "  ]\n";
	outFile << "}\n";
	outFile.close();

	return true;
}

// ==============================================================================
// Output Formatter
// ==============================================================================
void RdtscBenchmark::PrintResultsTable(const std::vector<BENCHMARK_RESULT>& Results, DWORD CoreId, uint32_t Iterations)
{
	std::cout << "\n";
	std::cout << "========================================================================================================================\n";
	std::cout << "                                   RDTSC HIGH-FREQUENCY BENCHMARK REPORT                                                \n";
	std::cout << "  Core Affinity: CPU Core #" << CoreId << " | Iterations: " << Iterations
		<< " | Serialization: mfence + lfence (Strict Memory Fence)\n";
	std::cout << "========================================================================================================================\n";
	std::cout << std::left
		<< std::setw(46) << "Target Operation"
		<< std::setw(14) << "Min (Cycles)"
		<< std::setw(14) << "Avg (Cycles)"
		<< std::setw(14) << "Max (Cycles)"
		<< std::setw(18) << "Total (Cycles)"
		<< "Diagnosis / Behavior\n";
	std::cout << "------------------------------------------------------------------------------------------------------------------------\n";

	for (const auto& r : Results)
	{
		std::cout << std::left
			<< std::setw(46) << r.Name
			<< std::setw(14) << r.MinCycles
			<< std::setw(14) << r.AvgCycles
			<< std::setw(14) << r.MaxCycles
			<< std::setw(18) << r.TotalCycles
			<< r.Diagnosis << "\n";

		// If breakdown stages exist, print segmented breakdown tree
		if (r.Breakdown.size() > 1)
		{
			for (size_t b = 0; b < r.Breakdown.size(); ++b)
			{
				const auto& st = r.Breakdown[b];
				double pct = r.MinCycles > 0 ? (double)st.Cycles * 100.0 / r.MinCycles : 0.0;
				std::cout << "    [+] Stage: " << std::left << std::setw(34) << st.StageName
					<< " -> " << std::setw(8) << st.Cycles << " cycles (" << std::fixed << std::setprecision(1) << pct << "%)\n";
			}
		}
	}

	std::cout << "========================================================================================================================\n";
	std::cout << "[*] Note: 'Min Cycles' filters out OS interrupts and scheduling noise to reveal true hardware/VM latency.\n";
	std::cout << "========================================================================================================================\n\n";
}

void RdtscBenchmark::RunAll(HANDLE DriverHandle, uint32_t Iterations, DWORD CoreId)
{
	std::cout << "[*] Initializing RDTSC Benchmark on CPU Core #" << CoreId << "...\n";
	std::cout << "[*] Locking thread affinity and setting REALTIME priority class...\n";

	ScopedCpuAffinity AffinityGuard(CoreId);
	if (!AffinityGuard.IsLocked())
	{
		std::cout << "[!] Warning: Failed to set thread affinity. Benchmark will continue with default affinity.\n";
	}

	std::vector<BENCHMARK_RESULT> results;

	// [1] RDTSC Baseline - ALWAYS MEASURED
	std::cout << "[*] [1/6] Measuring RDTSC + Memory Fence Baseline Overhead...\n";
	results.push_back(MeasureBaseline(Iterations));

	// [2] CPUID Leaf 0 (Vendor) - ALWAYS MEASURED (Unconditional VM-Exit)
	std::cout << "[*] [2/6] Measuring CPUID Leaf 0 (Vendor String)...\n";
	results.push_back(MeasureCpuid(0, "CPUID Leaf 0 (Vendor)", Iterations));

	// [3] CPUID Leaf 1 (Features) - ALWAYS MEASURED
	std::cout << "[*] [3/6] Measuring CPUID Leaf 1 (Feature Info)...\n";
	results.push_back(MeasureCpuid(1, "CPUID Leaf 1 (Features)", Iterations));

	// [4] MSR Benchmarks (Driver Ring 0 vs Ring 3 #GP Fault Comparison)
	bool driverMsrSuccess = false;
	if (DriverHandle != NULL && DriverHandle != INVALID_HANDLE_VALUE)
	{
		std::cout << "[*] [4/6] Querying EIHvCore driver for Ring 0 MSR Benchmarks (IOCTL_HV_BENCHMARK)...\n";
		std::vector<BENCHMARK_RESULT> kResults = QueryDriverBenchmark(DriverHandle, Iterations);
		if (!kResults.empty())
		{
			for (const auto& kr : kResults)
			{
				results.push_back(kr);
			}
			driverMsrSuccess = true;
			std::cout << "    [+] Ring 0 MSR queried successfully! True latency measured with ZERO #GP distortion.\n";
		}
		else
		{
			std::cout << "    [!] Driver IOCTL_HV_BENCHMARK call returned no items. Ensure the latest driver build is loaded.\n";
		}
	}
	else
	{
		std::cout << "    [-] Driver handle not available. Ring 0 MSR measurement skipped.\n";
	}

	// Always measure Ring 3 MSR so the user can directly observe the massive ~3900c #GP fault distortion against Ring 0
	std::cout << "[*] Measuring Ring 3 MSR 0x3A (Demonstrating user-mode #GP trap distortion)...\n";
	results.push_back(MeasureMsr(0x3A, "Ring 3 MSR 0x3A (#GP Fault Trap)", Iterations));

	// [5] Clean Syscall Baseline
	std::cout << "[*] Measuring Clean Native Syscall Baseline (NtYieldExecution)...\n";
	BENCHMARK_RESULT cleanSyscall = MeasureCleanSyscall(Iterations);
	uint64_t cleanBaselineMin = cleanSyscall.MinCycles;
	results.push_back(cleanSyscall);

	// [6] EPT Hooked Syscall (SSDT)
	std::cout << "[*] Measuring EPT Hooked Syscall (NtQuerySystemInformation SSDT)...\n";
	results.push_back(MeasureEptHookedSyscall(Iterations, cleanBaselineMin));

	// [7] EPT Hooked Syscall (NtCreateFile)
	std::cout << "[*] Measuring EPT Hooked Syscall (NtCreateFile via NUL)...\n";
	results.push_back(MeasureEptCreateFileSyscall(Iterations > 2000 ? 2000 : Iterations, cleanBaselineMin));

	PrintResultsTable(results, CoreId, Iterations);

	SaveToJson("benchmark_results.json", results, CoreId, Iterations);
	SaveToJson("latest_benchmark.json", results, CoreId, Iterations);
	std::cout << "[+] Benchmark data exported to 'benchmark_results.json' and 'latest_benchmark.json'\n\n";
}
